CREATE TABLE public.reader_social_profiles (user_id uuid PRIMARY KEY DEFAULT auth.uid(), handle text NOT NULL UNIQUE CHECK(handle ~ '^[a-z0-9_]{3,30}$'), name text NOT NULL DEFAULT '' CHECK(length(name)<=100), bio text NOT NULL DEFAULT '' CHECK(length(bio)<=1200), visibility text NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','friends','club','public')), club_id uuid, avatar_path text, cover_path text, CHECK ((visibility='club')=(club_id IS NOT NULL)), CHECK(avatar_path IS NULL OR avatar_path LIKE user_id::text||'/avatar/%'), CHECK(cover_path IS NULL OR cover_path LIKE user_id::text||'/cover/%'));
GRANT SELECT,INSERT,UPDATE ON public.reader_social_profiles TO authenticated; GRANT SELECT ON public.reader_social_profiles TO anon; GRANT ALL ON public.reader_social_profiles TO service_role;
ALTER TABLE public.reader_social_profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.reader_friendships(requester uuid NOT NULL, recipient uuid NOT NULL, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','accepted')), PRIMARY KEY(requester,recipient), CHECK(requester<>recipient));
GRANT SELECT ON public.reader_friendships TO authenticated; GRANT ALL ON public.reader_friendships TO service_role;
ALTER TABLE public.reader_friendships ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.reader_blocks(user_id uuid NOT NULL DEFAULT auth.uid(), blocked_id uuid NOT NULL, PRIMARY KEY(user_id,blocked_id), CHECK(user_id<>blocked_id));
GRANT SELECT ON public.reader_blocks TO authenticated; GRANT ALL ON public.reader_blocks TO service_role;
ALTER TABLE public.reader_blocks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.reader_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), target_id uuid NOT NULL, reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 5 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.reader_reports TO authenticated; GRANT ALL ON public.reader_reports TO service_role;
ALTER TABLE public.reader_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_reports ON public.reader_reports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND target_id<>auth.uid());
CREATE TABLE public.reader_clubs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120), description text NOT NULL DEFAULT '' CHECK(length(description)<=1200), timezone text NOT NULL DEFAULT 'UTC');
GRANT SELECT ON public.reader_clubs TO authenticated; GRANT ALL ON public.reader_clubs TO service_role;
ALTER TABLE public.reader_clubs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.reader_club_members(club_id uuid NOT NULL REFERENCES public.reader_clubs ON DELETE CASCADE, user_id uuid NOT NULL, role text NOT NULL DEFAULT 'member' CHECK(role IN ('owner','member')), joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(club_id,user_id));
GRANT SELECT ON public.reader_club_members TO authenticated; GRANT ALL ON public.reader_club_members TO service_role;
ALTER TABLE public.reader_club_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.reader_club_invites(club_id uuid NOT NULL REFERENCES public.reader_clubs ON DELETE CASCADE, user_id uuid NOT NULL, PRIMARY KEY(club_id,user_id));
GRANT SELECT ON public.reader_club_invites TO authenticated; GRANT ALL ON public.reader_club_invites TO service_role;
ALTER TABLE public.reader_club_invites ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reader_social_profiles ADD CONSTRAINT social_profile_club_fk FOREIGN KEY(club_id) REFERENCES public.reader_clubs;
CREATE FUNCTION public.reader_blocked(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT EXISTS(SELECT 1 FROM public.reader_blocks WHERE (user_id=a AND blocked_id=b) OR (user_id=b AND blocked_id=a))$$;
CREATE FUNCTION public.reader_club_member(c uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT u IS NOT NULL AND EXISTS(SELECT 1 FROM public.reader_club_members m JOIN public.reader_clubs g ON g.id=m.club_id WHERE m.club_id=c AND m.user_id=u AND NOT public.reader_blocked(g.owner_id,u))$$;
CREATE FUNCTION public.reader_can_view(owner_id uuid,v text,c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT owner_id=auth.uid() OR (NOT public.reader_blocked(owner_id,auth.uid()) AND (v='public' OR (v='friends' AND EXISTS(SELECT 1 FROM public.reader_friendships WHERE state='accepted' AND ((requester=owner_id AND recipient=auth.uid()) OR (recipient=owner_id AND requester=auth.uid())))) OR (v='club' AND public.reader_club_member(c,owner_id) AND public.reader_club_member(c,auth.uid()))))$$;
REVOKE ALL ON FUNCTION public.reader_blocked(uuid,uuid),public.reader_club_member(uuid,uuid),public.reader_can_view(uuid,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reader_blocked(uuid,uuid),public.reader_club_member(uuid,uuid),public.reader_can_view(uuid,text,uuid) TO authenticated,anon,service_role;
CREATE POLICY visible_social_profile ON public.reader_social_profiles FOR SELECT TO authenticated,anon USING(public.reader_can_view(user_id,visibility,club_id));
CREATE POLICY create_social_profile ON public.reader_social_profiles FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND (club_id IS NULL OR public.reader_club_member(club_id,auth.uid())));
CREATE POLICY edit_social_profile ON public.reader_social_profiles FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND (club_id IS NULL OR public.reader_club_member(club_id,auth.uid())));
CREATE POLICY own_friendships ON public.reader_friendships FOR SELECT TO authenticated USING(requester=auth.uid() OR recipient=auth.uid());
CREATE POLICY own_blocks ON public.reader_blocks FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY member_clubs ON public.reader_clubs FOR SELECT TO authenticated USING(public.reader_club_member(id,auth.uid()) OR EXISTS(SELECT 1 FROM public.reader_club_invites i WHERE i.club_id=id AND i.user_id=auth.uid() AND NOT public.reader_blocked(owner_id,auth.uid())));
CREATE POLICY member_roster ON public.reader_club_members FOR SELECT TO authenticated USING(public.reader_club_member(club_id,auth.uid()) AND NOT public.reader_blocked(user_id,auth.uid()));
CREATE POLICY own_invites ON public.reader_club_invites FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.reader_friend_action(p_handle text,p_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE target uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión.'; END IF; SELECT user_id INTO STRICT target FROM public.reader_social_profiles WHERE handle=lower(trim(leading '@' from p_handle)); IF target=auth.uid() THEN RAISE EXCEPTION 'Elige otra persona.'; END IF; IF p_action='block' THEN INSERT INTO public.reader_blocks VALUES(auth.uid(),target) ON CONFLICT DO NOTHING; DELETE FROM public.reader_friendships WHERE (requester=target AND recipient=auth.uid()) OR (requester=auth.uid() AND recipient=target); ELSIF p_action='unblock' THEN DELETE FROM public.reader_blocks WHERE user_id=auth.uid() AND blocked_id=target; ELSE IF public.reader_blocked(target,auth.uid()) THEN RAISE EXCEPTION 'No disponible.'; END IF; IF p_action='request' THEN IF EXISTS(SELECT 1 FROM public.reader_friendships WHERE requester=target AND recipient=auth.uid()) THEN RAISE EXCEPTION 'Ya existe una solicitud entrante.'; END IF; INSERT INTO public.reader_friendships VALUES(auth.uid(),target,'pending') ON CONFLICT DO NOTHING; ELSIF p_action='accept' THEN UPDATE public.reader_friendships SET state='accepted' WHERE requester=target AND recipient=auth.uid() AND state='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'No hay solicitud entrante.'; END IF; ELSIF p_action IN ('reject','remove') THEN DELETE FROM public.reader_friendships WHERE (requester=target AND recipient=auth.uid()) OR (requester=auth.uid() AND recipient=target); ELSE RAISE EXCEPTION 'Acción inválida.'; END IF; END IF; END $$;
CREATE FUNCTION public.reader_connections() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(jsonb_build_object('handle',p.handle,'state',f.state,'incoming',f.recipient=auth.uid())), '[]'::jsonb) FROM public.reader_friendships f JOIN public.reader_social_profiles p ON p.user_id=CASE WHEN f.requester=auth.uid() THEN f.recipient ELSE f.requester END WHERE (f.requester=auth.uid() OR f.recipient=auth.uid()) AND NOT public.reader_blocked(p.user_id,auth.uid())$$;
CREATE FUNCTION public.reader_club_action(p_action text,p_club uuid DEFAULT NULL,p_name text DEFAULT '',p_description text DEFAULT '',p_handle text DEFAULT '',p_zone text DEFAULT 'UTC') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE c public.reader_clubs; target uuid; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión.'; END IF; IF p_action='create' THEN IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name=p_zone) THEN RAISE EXCEPTION 'Zona horaria inválida.'; END IF; INSERT INTO public.reader_clubs(owner_id,name,description,timezone) VALUES(auth.uid(),p_name,p_description,p_zone) RETURNING id INTO result; INSERT INTO public.reader_club_members(club_id,user_id,role) VALUES(result,auth.uid(),'owner'); RETURN result; END IF; SELECT * INTO STRICT c FROM public.reader_clubs WHERE id=p_club FOR UPDATE; IF public.reader_blocked(c.owner_id,auth.uid()) THEN RAISE EXCEPTION 'No disponible.'; END IF; IF p_action='join' THEN DELETE FROM public.reader_club_invites WHERE club_id=c.id AND user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Necesitas una invitación.'; END IF; INSERT INTO public.reader_club_members(club_id,user_id) VALUES(c.id,auth.uid()) ON CONFLICT DO NOTHING; ELSIF p_action='decline' THEN DELETE FROM public.reader_club_invites WHERE club_id=c.id AND user_id=auth.uid(); ELSIF p_action='leave' THEN IF c.owner_id=auth.uid() THEN RAISE EXCEPTION 'La persona propietaria conserva el club.'; END IF; DELETE FROM public.reader_club_members WHERE club_id=c.id AND user_id=auth.uid(); ELSE IF c.owner_id<>auth.uid() THEN RAISE EXCEPTION 'Solo la persona propietaria.'; END IF; IF p_action='edit' THEN UPDATE public.reader_clubs SET name=p_name,description=p_description WHERE id=c.id; ELSE SELECT user_id INTO STRICT target FROM public.reader_social_profiles WHERE handle=lower(trim(leading '@' from p_handle)); IF target=c.owner_id OR public.reader_blocked(c.owner_id,target) THEN RAISE EXCEPTION 'No disponible.'; END IF; IF p_action='invite' THEN INSERT INTO public.reader_club_invites VALUES(c.id,target) ON CONFLICT DO NOTHING; ELSIF p_action='remove' THEN DELETE FROM public.reader_club_members WHERE club_id=c.id AND user_id=target; DELETE FROM public.reader_club_invites WHERE club_id=c.id AND user_id=target; ELSE RAISE EXCEPTION 'Acción inválida.'; END IF; END IF; END IF; RETURN c.id; END $$;
CREATE TABLE public.reader_shares(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), kind text NOT NULL CHECK(kind IN ('book','rating','list','bingo')), source_id uuid NOT NULL, visibility text NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','friends','club','public')), club_id uuid REFERENCES public.reader_clubs, UNIQUE(user_id,kind,source_id), CHECK((visibility='club')=(club_id IS NOT NULL)));
GRANT SELECT ON public.reader_shares TO authenticated,anon; GRANT ALL ON public.reader_shares TO service_role;
ALTER TABLE public.reader_shares ENABLE ROW LEVEL SECURITY;
CREATE POLICY visible_shares ON public.reader_shares FOR SELECT TO authenticated,anon USING(public.reader_can_view(user_id,visibility,club_id));
CREATE FUNCTION public.reader_share(p_kind text,p_source uuid,p_visibility text,p_club uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE result uuid; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.reader_social_profiles WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Primero guarda tu perfil.'; END IF; IF p_club IS NOT NULL AND NOT public.reader_club_member(p_club,auth.uid()) THEN RAISE EXCEPTION 'No perteneces al club.'; END IF; IF NOT ((p_kind IN ('book','rating') AND EXISTS(SELECT 1 FROM public.books WHERE id=p_source AND user_id=auth.uid())) OR (p_kind='list' AND EXISTS(SELECT 1 FROM public.reader_lists WHERE id=p_source AND user_id=auth.uid())) OR (p_kind='bingo' AND EXISTS(SELECT 1 FROM public.reader_bingos WHERE id=p_source AND user_id=auth.uid() AND state='active'))) THEN RAISE EXCEPTION 'Contenido no disponible.'; END IF; INSERT INTO public.reader_shares(user_id,kind,source_id,visibility,club_id) VALUES(auth.uid(),p_kind,p_source,p_visibility,p_club) ON CONFLICT(user_id,kind,source_id) DO UPDATE SET visibility=excluded.visibility,club_id=excluded.club_id RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.reader_share_payload(p_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE s public.reader_shares; payload jsonb; BEGIN SELECT * INTO s FROM public.reader_shares WHERE id=p_id; IF NOT FOUND OR NOT public.reader_can_view(s.user_id,s.visibility,s.club_id) THEN RETURN NULL; END IF; IF s.kind='book' THEN SELECT jsonb_build_object('title',title,'author',author) INTO payload FROM public.books WHERE id=s.source_id AND user_id=s.user_id; ELSIF s.kind='rating' THEN SELECT jsonb_build_object('title',title,'author',author,'stars',user_rating) INTO payload FROM public.books WHERE id=s.source_id AND user_id=s.user_id; ELSIF s.kind='list' THEN SELECT jsonb_build_object('title',name,'description',description,'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('title',coalesce(b.title,w.title),'author',coalesce(b.author,w.author)) ORDER BY i.position,i.id),'[]'::jsonb) FROM public.reader_list_items i LEFT JOIN public.books b ON b.id=i.book_id AND b.user_id=s.user_id LEFT JOIN public.reader_wishes w ON w.id=i.wish_id AND w.user_id=s.user_id WHERE i.list_id=l.id AND i.user_id=s.user_id)) INTO payload FROM public.reader_lists l WHERE id=s.source_id AND user_id=s.user_id; ELSIF s.kind='bingo' THEN SELECT jsonb_build_object('title',title,'purpose',purpose,'size',size,'cells',cells,'starts_on',starts_on,'ends_on',ends_on,'allow_reuse',allow_reuse) INTO payload FROM public.reader_bingos WHERE id=s.source_id AND user_id=s.user_id AND state='active'; END IF; RETURN payload; END $$;
ALTER TABLE public.reader_bingos ADD COLUMN shared_source_id uuid REFERENCES public.reader_shares;
CREATE UNIQUE INDEX reader_bingo_copy_once ON public.reader_bingos(user_id,shared_source_id) WHERE shared_source_id IS NOT NULL;
CREATE FUNCTION public.reader_copy_bingo(p_share uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE s public.reader_shares; b public.reader_bingos; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión.'; END IF; SELECT * INTO STRICT s FROM public.reader_shares WHERE id=p_share FOR UPDATE; IF s.kind<>'bingo' OR NOT public.reader_can_view(s.user_id,s.visibility,s.club_id) THEN RAISE EXCEPTION 'No disponible.'; END IF; SELECT id INTO result FROM public.reader_bingos WHERE user_id=auth.uid() AND shared_source_id=s.id; IF FOUND THEN RETURN result; END IF; SELECT * INTO STRICT b FROM public.reader_bingos WHERE id=s.source_id AND user_id=s.user_id AND state='active'; INSERT INTO public.reader_bingos(user_id,title,purpose,size,cells,starts_on,ends_on,allow_reuse,shared_source_id) VALUES(auth.uid(),b.title,b.purpose,b.size,b.cells,b.starts_on,b.ends_on,b.allow_reuse,s.id) RETURNING id INTO result; UPDATE public.reader_bingos SET state='active' WHERE id=result; RETURN result; END $$;
CREATE TABLE public.reader_joint_readings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), club_id uuid NOT NULL REFERENCES public.reader_clubs ON DELETE CASCADE, title text NOT NULL, author text NOT NULL, isbn text, chapters integer NOT NULL DEFAULT 1 CHECK(chapters BETWEEN 1 AND 1000), goal text NOT NULL DEFAULT '' CHECK(length(goal)<=1200), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.reader_joint_readings TO authenticated; GRANT ALL ON public.reader_joint_readings TO service_role;
ALTER TABLE public.reader_joint_readings ENABLE ROW LEVEL SECURITY;
CREATE POLICY member_readings ON public.reader_joint_readings FOR SELECT TO authenticated USING(public.reader_club_member(club_id,auth.uid()));
CREATE TABLE public.reader_joint_participants(reading_id uuid NOT NULL REFERENCES public.reader_joint_readings ON DELETE CASCADE, user_id uuid NOT NULL, book_id uuid NOT NULL REFERENCES public.books ON DELETE CASCADE, joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(reading_id,user_id));
GRANT SELECT ON public.reader_joint_participants TO authenticated; GRANT ALL ON public.reader_joint_participants TO service_role;
ALTER TABLE public.reader_joint_participants ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_joint_edition ON public.reader_joint_participants FOR SELECT TO authenticated USING(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.reader_joint_readings r WHERE r.id=reading_id AND public.reader_club_member(r.club_id,auth.uid())));
CREATE FUNCTION public.reader_joint_action(p_action text,p_club uuid DEFAULT NULL,p_reading uuid DEFAULT NULL,p_book uuid DEFAULT NULL,p_chapters integer DEFAULT 1,p_goal text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE b public.books; r public.reader_joint_readings; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión.'; END IF; IF p_action='create' THEN IF NOT EXISTS(SELECT 1 FROM public.reader_clubs WHERE id=p_club AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'Solo la persona propietaria.'; END IF; SELECT * INTO STRICT b FROM public.books WHERE id=p_book AND user_id=auth.uid(); INSERT INTO public.reader_joint_readings(club_id,title,author,isbn,chapters,goal) VALUES(p_club,b.title,b.purpose,b.isbn,p_chapters,p_goal) RETURNING id INTO result; RETURN result; END IF; SELECT * INTO STRICT r FROM public.reader_joint_readings WHERE id=p_reading; IF NOT public.reader_club_member(r.club_id,auth.uid()) THEN RAISE EXCEPTION 'No perteneces al club.'; END IF; IF p_action='leave' THEN DELETE FROM public.reader_joint_participants WHERE reading_id=r.id AND user_id=auth.uid(); RETURN r.id; END IF; IF p_action<>'join' THEN RAISE EXCEPTION 'Acción inválida.'; END IF; SELECT * INTO STRICT b FROM public.books WHERE id=p_book AND user_id=auth.uid(); IF public.reader_identity(b.title,b.author)<>public.reader_identity(r.title,r.author) AND (public.reader_isbn(b.isbn)='' OR public.reader_isbn(b.isbn)<>public.reader_isbn(r.isbn)) THEN RAISE EXCEPTION 'Elige una edición de esta lectura.'; END IF; INSERT INTO public.reader_joint_participants(reading_id,user_id,book_id) VALUES(r.id,auth.uid(),b.id) ON CONFLICT(reading_id,user_id) DO UPDATE SET book_id=excluded.book_id; RETURN r.id; END $$;
CREATE FUNCTION public.reader_joint_percent(p_reading uuid,p_user uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT CASE WHEN b.pages>0 THEN least(100,greatest(0,(b.current_page::numeric*100/b.pages)::integer)) ELSE 0 END FROM public.reader_joint_participants p JOIN public.reader_joint_readings r ON r.id=p.reading_id JOIN public.books b ON b.id=p.book_id AND b.user_id=p.user_id WHERE p.reading_id=p_reading AND p.user_id=p_user AND public.reader_club_member(r.club_id,auth.uid()) AND public.reader_club_member(r.club_id,p.user_id) AND NOT public.reader_blocked(p.user_id,auth.uid())$$;
CREATE TABLE public.reader_joint_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reading_id uuid NOT NULL REFERENCES public.reader_joint_readings ON DELETE CASCADE, user_id uuid NOT NULL DEFAULT auth.uid(), chapter integer NOT NULL CHECK(chapter>=1), body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 3000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.reader_joint_comments TO authenticated; GRANT ALL ON public.reader_joint_comments TO service_role;
ALTER TABLE public.reader_joint_comments ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.reader_chapter_access(p_reading uuid,p_chapter integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT p_chapter BETWEEN 1 AND r.chapters AND coalesce(public.reader_joint_percent(r.id,auth.uid()),0)>=ceil(p_chapter*100.0/r.chapters) FROM public.reader_joint_readings r WHERE r.id=p_reading AND public.reader_club_member(r.club_id,auth.uid())$$;
CREATE POLICY spoiler_comments ON public.reader_joint_comments FOR SELECT TO authenticated USING(public.reader_chapter_access(reading_id,chapter) AND NOT public.reader_blocked(user_id,auth.uid()));
CREATE POLICY write_spoiler_comments ON public.reader_joint_comments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.reader_chapter_access(reading_id,chapter));
CREATE POLICY delete_own_comments ON public.reader_joint_comments FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.reader_joint_summary(p_reading uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE r public.reader_joint_readings; zone text; days date[]; streak integer:=0; cursor_day date; people jsonb; BEGIN SELECT * INTO STRICT r FROM public.reader_joint_readings WHERE id=p_reading; IF NOT public.reader_club_member(r.club_id,auth.uid()) THEN RAISE EXCEPTION 'No perteneces al club.'; END IF; SELECT timezone INTO zone FROM public.reader_clubs WHERE id=r.club_id; WITH events AS (SELECT p.user_id,s.day FROM public.reader_joint_participants p JOIN public.reading_sessions s ON s.book_id=p.book_id WHERE p.reading_id=r.id AND s.to_page>s.from_page AND s.created_at>=p.joined_at AND public.reader_club_member(r.club_id,p.user_id) AND NOT public.reader_blocked(p.user_id,auth.uid()) UNION SELECT p.user_id,c.streak_day FROM public.reader_joint_participants p JOIN public.completed_readings c ON c.book_id=p.book_id WHERE p.reading_id=r.id AND c.streak_day IS NOT NULL AND c.finished_at>=p.joined_at AND public.reader_club_member(r.club_id,p.user_id) AND NOT public.reader_blocked(p.user_id,auth.uid())) SELECT array_agg(DISTINCT day) INTO days FROM events; cursor_day:=(now() AT TIME ZONE zone)::date; IF NOT cursor_day=ANY(coalesce(days,'{}'::date[])) THEN cursor_day:=cursor_day-1; END IF; WHILE cursor_day=ANY(coalesce(days,'{}'::date[])) LOOP streak:=streak+1; cursor_day:=cursor_day-1; END LOOP; SELECT coalesce(jsonb_agg(jsonb_build_object('handle',coalesce(sp.handle,'lector'),'percent',public.reader_joint_percent(r.id,p.user_id),'days',(SELECT count(DISTINCT d) FROM (SELECT s.day d FROM public.reading_sessions s WHERE s.book_id=p.book_id AND s.to_page>s.from_page AND s.created_at>=p.joined_at UNION SELECT c.streak_day FROM public.completed_readings c WHERE c.book_id=p.book_id AND c.streak_day IS NOT NULL AND c.finished_at>=p.joined_at) e))),'[]'::jsonb) INTO people FROM public.reader_joint_participants p LEFT JOIN public.reader_social_profiles sp ON sp.user_id=p.user_id AND public.reader_can_view(sp.user_id,sp.visibility,sp.club_id) WHERE p.reading_id=r.id AND public.reader_club_member(r.club_id,p.user_id) AND NOT public.reader_blocked(p.user_id,auth.uid()); RETURN jsonb_build_object('streak',streak,'participants',people,'my_percent',coalesce(public.reader_joint_percent(r.id,auth.uid()),0)); END $$;
REVOKE ALL ON FUNCTION public.reader_friend_action(text,text),public.reader_connections(),public.reader_club_action(text,uuid,text,text,text,text),public.reader_share(text,uuid,text,uuid),public.reader_copy_bingo(uuid),public.reader_joint_action(text,uuid,uuid,uuid,integer,text),public.reader_joint_percent(uuid,uuid),public.reader_chapter_access(uuid,integer),public.reader_joint_summary(uuid),public.reader_share_payload(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reader_friend_action(text,text),public.reader_connections(),public.reader_club_action(text,uuid,text,text,text,text),public.reader_share(text,uuid,text,uuid),public.reader_copy_bingo(uuid),public.reader_joint_action(text,uuid,uuid,uuid,integer,text),public.reader_joint_percent(uuid,uuid),public.reader_chapter_access(uuid,integer),public.reader_joint_summary(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.reader_share_payload(uuid) TO authenticated,anon;
CREATE POLICY reader_media_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='reader-profile-media' AND (storage.foldername(name))[1]=auth.uid()::text AND (storage.foldername(name))[2] IN ('avatar','cover') AND lower(storage.extension(name)) IN ('jpg','png','webp') AND (metadata->>'mimetype') IN ('image/jpeg','image/png','image/webp') AND (metadata->>'size')::bigint<=5242880);
CREATE POLICY reader_media_read ON storage.objects FOR SELECT TO authenticated,anon USING(bucket_id='reader-profile-media' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.reader_social_profiles p WHERE (p.avatar_path=name OR p.cover_path=name) AND public.reader_can_view(p.user_id,p.visibility,p.club_id))));
CREATE POLICY reader_media_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='reader-profile-media' AND (storage.foldername(name))[1]=auth.uid()::text);